/** The language of a locale among those known: `fr_CA` and `fr-CA` give `fr`; an unknown one gives English. */
export function language(locale, known = Object.keys(MESSAGES)) {
    const normal = (locale ?? '').replace('_', '-').toLowerCase();

    return known.find((name) => name === normal) ?? known.find((name) => name === normal.split('-')[0]) ?? 'en';
}

/**
 * A function giving a label by key, `{name}` placeholders replaced: the application's label first, then the
 * locale's, then the English one, then the key itself.
 */
export function translator(locale, overrides = {}) {
    const labels = { ...MESSAGES.en, ...MESSAGES[language(locale)], ...(Array.isArray(overrides) ? {} : overrides) };

    return (key, parameters = {}) =>
        (labels[key] ?? key).replace(/\{(\w+)\}/g, (whole, name) =>
            Object.hasOwn(parameters, name) ? String(parameters[name]) : whole,
        );
}
